create or replace function public.notify_reaction() returns trigger language plpgsql security definer set search_path=public as $$
declare owner uuid; begin select author_id into owner from public.posts where id=new.post_id; if owner is not null and owner<>new.user_id and coalesce((select reactions from public.notification_preferences where profile_id=owner),true) then insert into public.notifications(recipient_id,actor_id,type,title,body,link) select owner,new.user_id,'reaction','New reaction',coalesce(p.display_name,p.username,'An RCL member')||' reacted to your post.','/social#post-'||new.post_id from public.profiles p where p.id=new.user_id; end if; return new; end $$;